//
// Strategy: never trust the input tree. Parse with node-html-parser purely as a
// tokenizer, then REBUILD a clean serialization from scratch:
//   - only allowlisted tags are emitted
//   - disallowed tags are unwrapped (children kept) ...
//   - ... except <script>/<style>, which are dropped with their entire subtree
//   - comments are dropped
//   - the ONLY attribute that survives is href on <a>, and only if its scheme
//     (after entity-decoding and whitespace-stripping) is http, https or mailto
//
// Because the output is rebuilt character-by-character with aggressive
// escaping, no attribute/event handler/style/srcdoc from the input can ever
// leak into the result.

import { parse, HTMLElement } from "node-html-parser";

const ALLOWED_TAGS = new Set([
  "p", "br", "b", "i", "em", "strong", "a",
  "ul", "ol", "li", "code", "pre", "blockquote",
]);

const VOID_TAGS = new Set(["br"]);

const ALLOWED_SCHEMES = new Set(["http", "https", "mailto"]);

// ---------------------------------------------------------------------------
// Entity decoding (defense-in-depth; node-html-parser already decodes once,
// but we must defeat double/multi-encoded payloads such as
// `javascript&colon;` or `&#106;&#97;&#118;&#97;...`)
// ---------------------------------------------------------------------------

const NAMED_ENTITIES = {
  amp: "&", lt: "<", gt: ">", quot: '"', apos: "'",
  colon: ":", semi: ";", sol: "/", bsol: "\\", quest: "?",
  equals: "=", excl: "!", num: "#", period: ".",
  tab: "\t", newline: "\n", NewLine: "\n", nbsp: "\u00a0",
};

function decodeEntitiesOnce(str) {
  return str.replace(
    /&(#[xX][0-9a-fA-F]+|#[0-9]+|[a-zA-Z][a-zA-Z0-9]*);?/g,
    (match, body) => {
      if (body[0] === "#") {
        const code = body[1] === "x" || body[1] === "X"
          ? parseInt(body.slice(2), 16)
          : parseInt(body.slice(1), 10);
        if (!Number.isFinite(code) || code < 0 || code > 0x10ffff) return match;
        try { return String.fromCodePoint(code); } catch { return match; }
      }
      const named = NAMED_ENTITIES[body];
      return named !== undefined ? named : match;
    },
  );
}

function decodeEntitiesFully(str) {
  let prev = str;
  for (let i = 0; i < 6; i++) {
    const next = decodeEntitiesOnce(prev);
    if (next === prev) break;
    prev = next;
  }
  return prev;
}

// ---------------------------------------------------------------------------
// URL scheme check for <a href>
// ---------------------------------------------------------------------------

/**
 * Returns a safe href string, or null if the URL must be discarded.
 *
 * The check runs against a normalized copy of the value: fully
 * entity-decoded, with tabs/newlines/CRs (which browsers ignore inside URLs,
 * turning "jav\tascript:" into "javascript:") and leading/trailing control
 * characters stripped. The original (trimmed) value is returned when the
 * scheme passes. Scheme-less relative URLs are permitted.
 */
export function sanitizeHref(raw) {
  if (typeof raw !== "string") return null;

  let decoded = decodeEntitiesFully(raw);

  // Browsers strip \t \n \r anywhere in a URL and trim C0/space at the ends.
  const normalized = decoded.replace(/[\t\n\r]/g, "").replace(/^[\u0000-\u0020]+|[\u0000-\u0020]+$/g, "");

  const schemeMatch = /^([a-zA-Z][a-zA-Z0-9+.\-]*):/.exec(normalized);
  if (schemeMatch) {
    const scheme = schemeMatch[1].toLowerCase();
    if (!ALLOWED_SCHEMES.has(scheme)) return null;
    return raw.trim();
  }

  // No well-formed scheme. If a colon still appears before the first
  // "/", "?" or "#", it is either a malformed scheme or an obfuscation
  // attempt -> reject outright rather than guess what a browser would do.
  const colonAt = normalized.indexOf(":");
  if (colonAt !== -1) {
    const firstBoundary = Math.min(
      ...["/", "?", "#"].map((c) => {
        const i = normalized.indexOf(c);
        return i === -1 ? Infinity : i;
      }),
    );
    if (colonAt < firstBoundary) return null;
  }

  return raw.trim();
}

// ---------------------------------------------------------------------------
// Escaping
// ---------------------------------------------------------------------------

function escapeText(text) {
  return text.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

function escapeAttr(value) {
  return escapeText(value).replace(/"/g, "&quot;").replace(/'/g, "&#39;");
}

// ---------------------------------------------------------------------------
// Tree rebuilding
// ---------------------------------------------------------------------------

function render(node, out) {
  // Text node: escape and keep.
  if (node.nodeType === 3) {
    out.push(escapeText(node.text));
    return;
  }

  // Comments (nodeType 8) and anything exotic: drop silently.
  if (node.nodeType !== 1) return;
  if (!(node instanceof HTMLElement)) return;

  const tag = (node.rawTagName || "").toLowerCase();

  // Disallowed tag...
  if (!ALLOWED_TAGS.has(tag)) {
    // ...dropped entirely along with its content for script/style,
    if (tag === "script" || tag === "style") return;
    // ...unwrapped (text content kept) for everything else.
    for (const child of node.childNodes) render(child, out);
    return;
  }

  // Allowed tag: emit a fresh, minimal open tag.
  out.push(`<${tag}`);
  if (tag === "a") {
    const href = sanitizeHref(node.getAttribute("href"));
    if (href !== null && href !== "") {
      out.push(` href="${escapeAttr(href)}"`);
    }
  }
  out.push(">");

  for (const child of node.childNodes) render(child, out);

  out.push(VOID_TAGS.has(tag) ? "" : `</${tag}>`);
}

/**
 * Sanitize an untrusted HTML fragment.
 * @param {string} html
 * @returns {string} sanitized HTML
 */
export function sanitize(html) {
  if (typeof html !== "string") return "";
  const root = parse(html, { comment: true });
  const out = [];
  for (const child of root.childNodes) render(child, out);
  return out.join("");
}

export { ALLOWED_TAGS, ALLOWED_SCHEMES };
