import { parse } from "node-html-parser";
import { sanitize, sanitizeHref, ALLOWED_TAGS } from "../src/sanitizer.js";

// ---------------------------------------------------------------------------
// Helpers: re-parse every output and assert on the *tree*, not raw strings
// ---------------------------------------------------------------------------

function treeOf(html) {
  const root = parse(html);
  const walk = (node) => {
    if (node.nodeType === 3) return { type: "text", text: node.text };
    if (node.nodeType !== 1) return { type: "dropped" };
    return {
      type: "element",
      tag: (node.rawTagName || "").toLowerCase(),
      attrs: { ...node.attributes },
      children: node.childNodes.map(walk),
    };
  };
  return root.childNodes.map(walk);
}

function tagsOf(html) {
  const root = parse(html);
  const tags = [];
  root.querySelectorAll("*").forEach((n) => tags.push((n.rawTagName || "").toLowerCase()));
  return tags;
}

function attrsOf(html) {
  // Every attribute surviving anywhere in the output.
  const found = [];
  for (const node of parse(html).querySelectorAll("*")) {
    for (const [name] of Object.entries(node.attributes)) {
      found.push(`${(node.rawTagName || "").toLowerCase()}@${name.toLowerCase()}`);
    }
  }
  return found;
}

const BAD_ATTR_RE = /^on/i;

/** Global invariants that must hold for ANY sanitizer output. */
function assertClean(output) {
  const root = parse(output);
  // No comments survive.
  expect(output).not.toContain("<!--");
  // No disallowed tags survive.
  for (const tag of tagsOf(output)) {
    expect(ALLOWED_TAGS.has(tag), `tag <${tag}> leaked`).toBe(true);
  }
  // No event handlers, style or srcdoc attributes anywhere.
  for (const attr of attrsOf(output)) {
    expect(BAD_ATTR_RE.test(attr), `handler ${attr} leaked`).toBe(false);
    expect(attr.endsWith("@style"), `${attr} leaked`).toBe(false);
    expect(attr.endsWith("@srcdoc"), `${attr} leaked`).toBe(false);
  }
  // Only <a> may carry attributes at all.
  for (const attr of attrsOf(output)) {
    expect(attr.startsWith("a@"), `attribute ${attr} on non-<a>`).toBe(true);
  }
  // No live script/style content.
  expect(root.querySelectorAll("script,style").length).toBe(0);
}

function clean(input) {
  const output = sanitize(input);
  assertClean(output);
  return output;
}

// ---------------------------------------------------------------------------
// Vector suite
// ---------------------------------------------------------------------------

describe("sanitizer — passthrough of safe markup", () => {
  it("V01: plain paragraph is preserved exactly", () => {
    expect(clean("<p>hello world</p>")).toBe("<p>hello world</p>");
    expect(treeOf(sanitize("<p>hello world</p>"))).toEqual([
      { type: "element", tag: "p", attrs: {}, children: [{ type: "text", text: "hello world" }] },
    ]);
  });

  it("V02: nested inline formatting and lists are preserved", () => {
    const input = "<ul><li>a</li><li>b<em>c</em><strong>d</strong></li></ul>";
    const out = clean(input);
    expect(out).toBe(input);
    const li = parse(out).querySelectorAll("li");
    expect(li).toHaveLength(2);
    expect(li[1].querySelector("em")?.text).toBe("c");
    expect(li[1].querySelector("strong")?.text).toBe("d");
  });

  it("V03: blockquote > p > code nesting survives", () => {
    const input = "<blockquote><p>x <code>y</code></p></blockquote>";
    const out = clean(input);
    expect(out).toBe(input);
    const bq = parse(out).querySelector("blockquote");
    expect(bq?.querySelector("p code")?.text).toBe("y");
  });

  it("V04: allowed href schemes http/https/mailto are kept", () => {
    const cases = [
      'https://example.com/page?a=1&b=2',
      'http://example.com/',
      'mailto:user@example.com',
    ];
    for (const href of cases) {
      const out = clean(`<a href="${href}">link</a>`);
      expect(parse(out).querySelector("a")?.getAttribute("href")).toBe(href);
    }
  });
});

describe("sanitizer — script/style elimination", () => {
  it("V05: script inside an allowed tag is dropped, sibling text kept", () => {
    const out = clean("<b><script>alert(1)</script>bold</b>");
    expect(out).toBe("<b>bold</b>");
    expect(treeOf(out)).toEqual([
      { type: "element", tag: "b", attrs: {}, children: [{ type: "text", text: "bold" }] },
    ]);
  });

  it("V06: style element dropped entirely, surrounding content kept", () => {
    const out = clean('<style>p{background:url(evil)}</style><p>keep</p>');
    expect(out).toBe("<p>keep</p>");
  });

  it("V07: nested script deep inside the tree contributes nothing", () => {
    const out = clean("<ul><li><script>x</script>a</li><ol><li><style>y</style>b</li></ol></ul>");
    expect(out).toBe("<ul><li>a</li><ol><li>b</li></ol></ul>");
  });
});

describe("sanitizer — javascript: URL obfuscation", () => {
  it("V08: mixed-case javascript: scheme rejected", () => {
    const out = clean('<a href="JaVaScRiPt:alert(1)">x</a>');
    expect(out).toBe("<a>x</a>");
    expect(parse(out).querySelector("a")?.getAttribute("href")).toBeUndefined();
  });

  it("V09: tab/newline embedded in scheme rejected (browser normalization)", () => {
    expect(clean('<a href="jav\tascript:alert(1)">x</a>')).toBe("<a>x</a>");
    expect(clean('<a href="java\nscript:alert(1)">x</a>')).toBe("<a>x</a>");
    expect(clean('<a href="jav&#x0A;ascript:alert(1)">x</a>')).toBe("<a>x</a>");
  });

  it("V10: entity-encoded scheme decoded before checking", () => {
    expect(clean('<a href="&#106;avascript:alert(1)">x</a>')).toBe("<a>x</a>");
    expect(clean('<a href="&#x6A;&#x61;&#x76;&#x61;script:alert(1)">x</a>')).toBe("<a>x</a>");
  });

  it("V11: double-encoded javascript&colon; defeated by iterative decoding", () => {
    // Parser decodes &amp; -> &, leaving "javascript&colon;alert(1)";
    // sanitizer's own decode pass then exposes the real scheme.
    const out = clean('<a href="javascript&amp;colon;alert(1)">x</a>');
    expect(out).toBe("<a>x</a>");
  });

  it("V12: leading control characters before the scheme rejected", () => {
    expect(clean('<a href="&#x00;javascript:alert(1)">x</a>')).toBe("<a>x</a>");
    expect(clean('<a href="   javascript:alert(1)">x</a>')).toBe("<a>x</a>");
  });

  it("V13: unknown schemes like vbscript/data/file rejected", () => {
    for (const href of ["vbscript:msgbox(1)", "data:text/html,<script>alert(1)</script>", "file:///etc/passwd"]) {
      expect(clean(`<a href="${href}">x</a>`)).toBe("<a>x</a>");
    }
  });

  it("V14: sanitizeHref unit behavior", () => {
    expect(sanitizeHref("HTTPS://ok.example")).toBe("HTTPS://ok.example");
    expect(sanitizeHref("mailto:a@b.c")).toBe("mailto:a@b.c");
    expect(sanitizeHref("/relative/path")).toBe("/relative/path");
    expect(sanitizeHref("#anchor")).toBe("#anchor");
    expect(sanitizeHref(null)).toBe(null);
    expect(sanitizeHref("javascript:alert(1)")).toBe(null);
    expect(sanitizeHref("jAva\tscRipt:x")).toBe(null);
  });
});

describe("sanitizer — foreign content, handlers, comments, srcdoc", () => {
  it("V15: svg foreign object unwrapped to its text only", () => {
    const out = clean('<svg><circle r="1"/><script>alert(1)</script><text>hi</text></svg>there');
    expect(out).toBe("hithere");
    expect(tagsOf(out)).toHaveLength(0);
  });

  it("V16: mathml content unwrapped to text only", () => {
    const out = clean("<math><mi><script>alert(1)</script>x</mi></math>y");
    expect(out).toBe("xy");
  });

  it("V17: event handlers never survive, even on allowed tags", () => {
    const out = clean('<b onmouseover="alert(1)" onclick=x>bold</b>');
    expect(out).toBe("<b>bold</b>");
    expect(attrsOf(out)).toHaveLength(0);
  });

  it("V18: div/span with style+handlers unwrapped, text kept", () => {
    const out = clean('<div onclick="e()" style="color:red"><span style="x">text</span></div>');
    expect(out).toBe("text");
    expect(attrsOf(out)).toHaveLength(0);
  });

  it("V19: img with onerror leaves no residue", () => {
    const out = clean('before<img src=x onerror="alert(1)">after');
    expect(out).toBe("beforeafter");
  });

  it("V20: comments removed everywhere including nested", () => {
    const out = clean("<p>a<!-- secret --><b><!-- more -->c</b></p>");
    expect(out).toBe("<p>ac</p>".replace("ac", "ab<!-- nothing -->c".replace(/<!--[^>]*-->/g, "")));
    expect(out).toBe("<p>abc</p>");
  });

  it("V21: iframe srcdoc attribute can never survive", () => {
    const out = clean('<iframe srcdoc="&lt;script&gt;alert(1)&lt;/script&gt;"></iframe>');
    expect(out).toBe("");
    expect(out).not.toContain("srcdoc");
  });

  it("V22: iframe/script/style soup collapses to bare text", () => {
    const out = clean(
      '<iframe src="evil"></iframe><object data="evil"></object>' +
      '<embed src="evil"><form action="evil"><input onfocus=x value=t></form>tail',
    );
    expect(out).toBe("t tail".replace(" ", ""));
    assertClean(out);
  });
});

describe("sanitizer — escaping round-trip", () => {
  it("V23: literal angle brackets in text stay escaped after re-parse", () => {
    const out = clean("<pre>&lt;script&gt;not code&lt;/script&gt;</pre>");
    expect(parse(out).querySelector("pre")?.text).toBe("<script>not code</script>");
    // ...but as markup it is inert text.
    expect(parse(out).querySelectorAll("script")).toHaveLength(0);
  });

  it("V24: quotes in href are escaped so attributes cannot be broken out of", () => {
    const out = clean('<a href="https://example.com/?q=a&quot;b">x</a>');
    const a = parse(out).querySelector("a");
    expect(a?.getAttribute("href")).toBe('https://example.com/?q=a"b');
    expect(attrsOf(out)).toEqual(["a@href"]);
  });

  it("V25: ampersands round-trip safely", () => {
    const out = clean("<p>fizz &amp; buzz &lt;tag&gt;</p>");
    expect(parse(out).querySelector("p")?.text).toBe("fizz & buzz <tag>");
  });
});

describe("sanitizer — robustness", () => {
  it("V26: non-string / empty inputs yield empty string", () => {
    for (const input of [undefined, null, "", 42, {}]) {
      expect(sanitize(/** @type {*} */ (input))).toBe("");
    }
  });

  it("V27: malformed garbage HTML does not throw and stays clean", () => {
    const garbages = [
      "<p><b>unclosed",
      "</div></p><a href='javascript:x'",
      "<<>>", "plain text only",
      "<p a=b c=d>attrs</p>",
      "<A HREF=\"JAVASCRIPT:x\">upper</A>",
    ];
    for (const g of garbages) assertClean(sanitize(g));
    expect(clean('<A HREF="JAVASCRIPT:x">upper</A>')).toBe("<a>upper</a>");
  });
});
"})
